function applyToExisting(regions){
  try{
    const app=getApp(),parties=getParties();
    app.collegeValues=app.collegeValues&&typeof app.collegeValues==="object"?app.collegeValues:{camera:{},senato:{}};
    app.collegeValues.camera=app.collegeValues.camera||{};app.collegeValues.senato=app.collegeValues.senato||{};
    app.regionalSenate=app.regionalSenate&&typeof app.regionalSenate==="object"?app.regionalSenate:{};
    app.regionalCustom=app.regionalCustom&&typeof app.regionalCustom==="object"?app.regionalCustom:{};
    regions.forEach(region=>{
      app.regionalSenate[region]=Object.fromEntries(Object.keys(parties).map(id=>[id,manualValue(region,id,"senato")]));
      app.regionalCustom[region]=true;
      parseColleges(CAM_COLLEGI,region).filter(c=>!c.special).forEach(c=>{app.collegeValues.camera[c.name]=Object.fromEntries(Object.keys(parties).map(id=>[id,manualValue(region,id,"camera")]));});
    });
    localStorage.setItem(APP_KEY,JSON.stringify(app));
    let legacy={};try{legacy=JSON.parse(localStorage.getItem("lombardia_sondaggi_v7")||"{}");}catch(_){legacy={};}
    legacy.circVotes=legacy.circVotes&&typeof legacy.circVotes==="object"?legacy.circVotes:{camera:{},senato:{}};
    legacy.circVotes.senato=legacy.circVotes.senato||{};
    regions.forEach(region=>{legacy.circVotes.senato[region]={};Object.keys(parties).forEach(id=>legacy.circVotes.senato[region][parties[id].name]=manualValue(region,id,"senato"));});
    localStorage.setItem("lombardia_sondaggi_v7",JSON.stringify(legacy));
    alert("Scenario applicato ai dati Sondaggi. La pagina verrà ricaricata per riallineare il modulo esistente.");
    window.location.reload();
  }catch(err){alert("Applicazione non riuscita: "+(err?.message||err));}
}
function ensureTrendHost(){
  const dashboardHost=document.getElementById("sg7content");
  const page=document.getElementById("page");
  const anchor=document.getElementById("tab-sondaggi");
  let current=document.getElementById("sg-trend-module");

  /* Il Trend appartiene alla schermata Sondaggi: deve vivere dentro #sg7content.
     La precedente priorità a #page lo collocava fuori dal contenitore visibile. */
  if(dashboardHost){
    if(!current){
      current=document.createElement("section");
      current.id="sg-trend-module";
      current.setAttribute("aria-label","Trend storico 2018 2022 e scenario regionale");
      dashboardHost.insertBefore(current,dashboardHost.firstChild);
    }else if(current.parentElement!==dashboardHost || current!==dashboardHost.firstElementChild){
      dashboardHost.insertBefore(current,dashboardHost.firstChild);
    }
    return current;
  }

  if(page&&anchor){
    if(!current){
      current=document.createElement("section");
      current.id="sg-trend-module";
      current.setAttribute("aria-label","Trend storico 2018 2022 e scenario regionale");
      page.insertBefore(current,anchor);
    }else if(current.parentElement!==page||current.nextElementSibling!==anchor){
      page.insertBefore(current,anchor);
    }
    return current;
  }

  return null;
}
let sgTrendObserverInstalled=false;
function installTrendObserver(){if(sgTrendObserverInstalled)return;sgTrendObserverInstalled=true;const root=document.documentElement||document.body;if(!root)return;let queued=false;const ensure=()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;const host=ensureTrendHost();if(host&&!host.dataset.sgTrendStarted){host.dataset.sgTrendStarted="1";render();}});};new MutationObserver(ensure).observe(root,{subtree:true,childList:true});ensure();setTimeout(ensure,250);setTimeout(ensure,750);setTimeout(ensure,1500);}
let sgTrendEventsInstalled=false;
function start(){injectStyle();const host=ensureTrendHost();if(host){if(!sgTrendEventsInstalled){sgTrendEventsInstalled=true;const refresh=()=>{S=loadTrend();const h=ensureTrendHost();if(h)render();};window.addEventListener("sondaggi-data-sync",refresh);window.addEventListener("sondaggi-v7-updated",refresh);window.addEventListener("storage",e=>{if(e.key===APP_KEY||e.key==="lombardia_sondaggi_v7")refresh();});}host.dataset.sgTrendStarted="1";render();}installTrendObserver();scheduleTrendSimulation(300);}
